    "body": "초단기 시장금리는 하루에서 며칠 사이로 돈을 빌리고 빌려줄 때의 금리이다. 은행끼리 하루 빌리는 콜금리(콜金利 · call rate)와 하루짜리 RP 금리가 대표적이다. 금리는 빌리는 기간(만기 滿期 · maturity)에 따라 이름이 나뉘어, 1년 이하는 단기, 몇 년에서 수십 년은 장기라 부르고 20년이 넘는 국채 금리는 초장기라고도 한다. 한국은행이 공개시장운영으로 직접 움직이는 것은 이 가운데 가장 짧은 초단기 금리이고, 단기와 장기 금리는 초단기 금리가 앞으로 어떻게 움직일지에 대한 시장의 예상을 따라 간접적으로 움직인다. 공개시장(公開市場 · open market)은 특정 상대와 따로 정하는 거래가 아니라, 여러 금융기관이 함께 참여해 경쟁으로 값이 정해지는 시장을 말한다. 채권시장이 대표적이다. 중앙은행이 어려운 은행 한 곳에 창구로 따로 돈을 빌려주는 것과 달리, 공개시장운영은 이 열린 시장에 들어가 여러 은행을 상대로 입찰 같은 방식으로 사고판다. 그래서 돈이 특정 은행이 아니라 시장 전체에 고르게 퍼지고, 그 결과가 시장 금리에 곧바로 드러난다. 한국은행이 쓰는 수단은 크게 셋이다. 첫째는 한국은행이 은행들에 며칠짜리로 돈을 넣어 주거나 은행들의 돈을 며칠 동안 묶어 두는 환매조건부매매(還買條件附賣買 · repurchase agreement, RP)이다. 환매(還買)는 \"도로 산다\"는 뜻으로, 채권을 넘긴 쪽이 정한 날 정한 값에 그 채권을 도로 사 오기로 조건을 붙인 매매라는 말이다. 한국은행이 은행들에 돈을 넣어 줄 때는 은행이 한국은행에 채권을 맡기고 한국은행의 돈을 받았다가, 며칠 뒤 한국은행에 이자를 얹어 돈을 돌려주고 그 채권을 되찾아 간다. 한국은행이 은행들의 돈을 묶어 둘 때는 거꾸로 한국은행이 은행에 채권을 맡기고 은행의 돈을 받아 간다. 그동안 그 돈은 은행이 쓸 수 없고, 며칠 뒤 한국은행이 은행에 이자를 얹어 돈을 돌려주고 채권을 되찾아 온다. 둘째는 한국은행이 직접 증권을 찍어 은행 등에 팔고 그 값으로 낸 은행들의 돈을 만기까지 묶어 두는 통화안정증권 발행이다. 셋째는 한국은행이 은행 등에게서 국채를 아예 사거나 그들에게 파는 단순매매이다. 한국은행이 은행에게서 채권을 사들이면 그 값이 은행의 한국은행 계좌로 들어가 시중에 돈이 늘고, 초단기 금리는 내려가는 쪽으로 움직인다. 반대로 한국은행이 은행에 채권을 팔면 그 값만큼 은행의 한국은행 계좌에서 돈이 빠져나가 시중 돈이 줄고, 그 금리는 오르는 쪽으로 움직인다. 예를 들어 은행들 사이에 돈이 모자라 하루짜리 금리가 기준금리 3.00%보다 높은 3.10%로 오르려 하면, 한국은행이 은행들에게서 채권을 RP로 사들여 돈을 넣어 준다. 그러면 돈이 남게 된 은행들은 그 돈을 다른 은행에 빌려주려 한다. 한국은행 계좌에 그냥 두면 이자가 없거나 적지만, 하루라도 빌려주면 이자를 받기 때문이다. 은행도 이익을 내야 하는 회사여서 노는 돈을 그냥 두지 않는다. 빌리는 쪽에는 그날 결제할 돈이나 법으로 쌓아야 할 지급준비금이 모자란 은행이 늘 있다. 빌려주려는 은행이 많아지면 서로 낮은 금리를 불러 경쟁하므로 금리가 3.00% 근처로 돌아온다. 말뿐인 금리 발표와 달리, 실제 매매로 하루짜리 금리 같은 아주 짧은 금리를 정책금리 근처에 붙여 둔다. 이 거래가 막히면 정책금리와 시장금리 사이가 벌어져 자금 배분이 출렁인다.",
