    "body": "중앙은행이 가계와 기업이 예상하는 앞으로의 물가 상승률(기대인플레이션 期待인플레이션 · inflation expectation)을 목표 숫자 근처에 붙들어 두려고 쓴다. 배가 닻을 내려 한자리에 머물듯 사람들의 예상을 한 숫자에 고정한다는 뜻에서 기대를 고정한다(anchoring)고도 한다. 한국은행의 목표는 소비자물가 상승률 2%이다. 사람들이 \"물가는 앞으로도 대략 2%씩 오를 것\"이라고 믿으면, 노사는 임금을 그 정도 올리고 기업도 가격을 그 정도 올려 정한다. 그러면 실제 물가도 2% 근처에 머물기 쉽다. 반대로 사람들이 5% 오를 것이라고 믿기 시작하면 임금과 가격을 미리 5%씩 올려 정해, 그 믿음이 실제 물가를 끌어올린다. 목표를 숫자로 밝히고, 실제 물가가 목표에서 벗어나면 기준금리를 조절하거나 소통을 함으로써 되돌리려고 한다. 여기서 소통은 중앙은행이 앞으로 어떻게 할지를 말로 알리는 것이다. 결정문과 기자회견, 경제 전망에서 \"물가가 목표로 돌아올 때까지 금리를 높게 유지하겠다\"고 밝히면, 사람들은 금리가 당분간 내리지 않겠다고 보고 미리 지출과 가격 계획을 조정한다. 금리를 실제로 바꾸기 전에 말만으로도 시장 금리와 물가 기대가 움직이므로, 소통도 금리만큼 중요한 손잡이가 된다(통화정책 커뮤니케이션 참고). 물가가 목표보다 높고 수요가 강하면 금리를 올려 지출을 늦추고, 목표를 밑돌며 경기가 식으면 금리를 낮추는 쪽이 일반적이다. 목표가 뚜렷하면 임금과 가격을 정할 때 참고점이 생긴다. 어려운 경우는 공급 충격(供給 衝擊 · supply shock)이다. 공급 충격은 사려는 쪽이 아니라 만드는 쪽에 갑자기 생긴 충격으로, 원유값이 치솟거나 전쟁과 흉작, 감염병으로 원자재와 부품이 끊기는 일이 그렇다. 만드는 비용이 오르니 물가는 오르고, 만들 수 있는 양은 줄어 경기는 나빠진다(비용인상 인플레이션, 스태그플레이션 참고). 사려는 사람이 많아져 생긴 수요 충격이라면 물가와 경기가 함께 달아오르므로 금리를 올리면 둘 다 식힐 수 있다. 그러나 공급 충격 때 금리를 올리면 물가는 잡혀도 이미 나빠진 경기가 더 나빠지고, 금리를 내리면 경기는 받쳐도 물가가 더 오른다. 금리를 내리면 빌리기 쉬워져 사람들이 더 사려 하는데, 공급이 막혀 만들 수 있는 양은 늘지 않으니 더 많은 돈이 줄어든 물건을 두고 다투게 되기 때문이다. 원화 값이 내려가 수입 원자재가 더 비싸지고, 사람들이 앞으로 물가가 더 오르리라 믿게 되는 것도 물가를 밀어 올린다. 사람들이 그렇게 믿는 것은 중앙은행이 일부러 물가를 올리려 한다고 봐서가 아니다. 물가가 오르는 와중에 금리를 내리는 모습을 보고, 중앙은행이 물가보다 경기를 먼저 챙기며 물가가 좀 올라도 참겠구나 하고 읽는 것이다. 정부의 빚이 크거나 정치의 압력이 셀 때 중앙은행이 금리를 올리기 어려우리라는 의심이 더해지기도 한다. 물가가 크게 오르는데도 정치 지도자의 뜻에 따라 금리를 내린 나라에서 통화 가치가 급락하고 물가가 더 치솟은 사례가 있다. 그래서 중앙은행이 물가 목표를 지킨다는 믿음, 곧 신뢰가 중요하고, 이 신뢰를 지키려고 여러 나라가 중앙은행이 정부의 지시를 받지 않고 금리를 정하도록 독립성을 법으로 보장한다. 1970년대 석유 파동 때 많은 나라가 이 갈림길에서 오랫동안 높은 물가와 실업을 함께 겪었다. 그래서 중앙은행은 공급 충격이 한 번 오르고 마는 일인지, 사람들의 물가 기대를 끌어올려 계속 번지는 일인지를 따져 대응을 고른다. 환율이나 금융안정이 물가 목표와 부딪히면 짧은 기간에는 목표를 벗어날 수 있다. 목표를 지키려는 의지를 설명하는 일도 금리 결정만큼 운영의 일부이다.",
