    "body": "고용 통계를 읽는 연구자와 정책 당국이 경기 순환과 일자리 엇갈림을 구분할 때 쓴다. 보통 실업이 줄면 빈 자리는 늘어 곡선은 오른쪽 아래로 기운다. 경기가 나빠져 실업이 늘고 빈 자리가 줄면 곡선 위를 반대편으로 움직인다. 곡선 전체가 바깥으로 밀리면, 일자리는 있는데 사람을 못 구하고 사람은 있는데 일을 못 찾는 미스매치가 커진 신호이다. 안쪽으로 들어오면 구인과 구직이 서로를 찾는 효율이 나아진 것으로 읽는다.",
