    "id": "t265",
    "title": "변동금리부채권(FRN)",
    "hanja": "變動金利附債券",
    "en": "floating rate note",
    "track": "bonds",
    "one": "이자 금액이 고정되지 않고, 기준 금리에 연동돼 일정 기간마다 다시 정해지는 채권을 말한다.",
    "body": "금리 변동을 나누어 가지려는 발행자와 투자자가 쓴다. 기준이 되는 금리에 발행자 신용을 반영한 가산 금리를 더해 다음 이자를 계산한다. 어느 회사가 액면 100억 원, 만기 3년, 이자는 석 달마다 \"CD금리 + 1%\"로 다시 정하는 채권을 냈다고 하자. CD금리는 은행들이 석 달짜리 양도성예금증서를 사고팔 때의 금리로, 단기 시장 금리의 대표 숫자이다. 처음 석 달 동안 CD금리가 연 3%이면 이자율은 연 4%이고, 석 달 치 이자는 100억 원 × 4% ÷ 4 = 1억 원이다. 다음 석 달에 CD금리가 3.5%로 오르면 이자율은 4.5%가 되어 이자는 1억 2,500만 원으로 늘고, 그다음 석 달에 2.5%로 내리면 3.5%가 되어 8,750만 원으로 준다. 회사의 신용에 따라 붙는 1%는 그대로이고, 시장 금리 부분만 따라 움직인다. 금리가 오르면 새로 받는 이자는 늘고, 채권 가격은 고정금리채(固定金利債 · fixed-rate bond)만큼 크게 떨어지지 않는 편이 많다. 시장 금리가 올라도 석 달 뒤면 이자가 따라 오르므로, 새 채권보다 불리한 기간이 길지 않아 값이 액면 100억 원 근처에 머물기 때문이다. 같은 때 연 4% 고정금리로 낸 3년짜리 채권은 시장 금리가 1%포인트 오르면 남은 기간 내내 낮은 이자를 받아야 하므로 값이 3% 가까이 내려간다. 다만 회사의 신용이 나빠지면 이야기가 다르다. 이 채권에 적힌 1%는 만기까지 그대로지만, 이제 이 회사에 새로 돈을 빌려주려는 투자자는 1.5%쯤은 받아야 한다고 여길 수 있다. 그러면 1%만 주는 이 채권을 사려는 사람은 그 모자란 0.5%포인트를 값을 깎아서 메우려 하므로 값이 내려간다. 3년이 남았다면 대략 0.5%포인트 × 3년 = 1.5%쯤, 곧 100억 원이 98억 5천만 원 근처로 내려가는 식이다. 바뀌는 것은 채권에 적힌 1%가 아니라 채권의 값이다. 금리가 내리면 이자 수입은 줄어든다. 석 달이라는 주기는 법이나 시장의 규칙이 아니라 채권을 낼 때 계약서에 적는 조건이다. 기준 금리를 석 달짜리 CD금리로 잡으면 주기도 석 달로 맞추는 일이 많을 뿐, 한 달이나 여섯 달로 정한 채권도 있다. 1%를 더하는 까닭은 CD금리가 은행끼리 석 달 빌려줄 때의 금리, 곧 꽤 안전한 쪽의 금리이기 때문이다. 이 회사에 돈을 빌려주는 투자자는 회사가 못 갚을 위험, 3년 동안 돈이 묶이는 부담, 팔고 싶을 때 쉽게 팔지 못할 부담을 더 진다. 그 대가로 받는 웃돈이 가산 금리(加算金利 · spread)이다. 가산 금리를 정하는 사람은 따로 없다. 회사와 채권 인수를 맡은 증권회사가 투자자들에게 얼마면 사겠느냐고 물어(수요예측 需要豫測 · book building) 사겠다는 쪽과 팔겠다는 쪽이 맞는 선에서 정해진다. 신용평가회사가 매긴 신용등급, 비슷한 등급 회사들이 최근 낸 채권의 가산 금리, 그때 시장의 분위기가 그 선을 움직인다. 발행자 신용이 나쁠수록 투자자가 더 큰 웃돈을 요구하므로 가산 금리는 넓어지는 경우가 많다. 한 번 낸 채권의 1%는 만기까지 고정된다. 계약서에 적힌 숫자라서 회사 신용이 나빠져도, 좋아져도 바뀌지 않는다. 대신 시장이 지금 이 회사에 요구하는 가산 금리는 날마다 움직이고, 그 차이는 채권 값으로 나타난다. 시장이 1.5%를 요구하게 되면 1%만 주는 이 채권은 값이 내려가고, 0.7%면 값이 오른다. 회사가 다음에 새로 내는 채권에는 그때의 가산 금리가 붙는다.",
    "watch": "이자가 변한다고 원금 상환 조건까지 바뀌는 것은 아니다. 원금 상환 조건은 빌린 원금(元金 · principal)을 언제, 얼마씩 돌려주느냐이다. 위 예라면 \"3년 뒤 만기에 100억 원을 한 번에 돌려준다\"가 그것이고, CD금리가 아무리 움직여도 이 약속은 그대로다. 바뀌는 것은 석 달마다 받는 이자의 금액뿐이다.",
