    "body": "1944년 브레튼우즈 회의를 계기로 주요국이 환율 안정을 위해 세운 체제이다. 미국은 외국 정부와 중앙은행이 달러를 가져오면 금 1온스당 35달러로 바꾸어 주는 약속(금태환 金兌換 · gold convertibility)을 지켰다. 다른 나라는 자기 나라 돈과 달러의 교환 비율을 하나로 정해 두고, 시장 환율이 그 비율에서 위아래 1% 안에 머물도록 지켰다. 일본은 1달러 = 360엔이었다. \"맞춰 관리했다\"는 것은 이 비율을 지키려고 그 나라 중앙은행이 직접 외환시장에서 사고팔았다는 뜻이다. 엔화를 팔고 달러를 사려는 사람이 많아 엔화 값이 떨어지려 하면 일본은행이 가진 달러를 팔고 엔화를 사들여 값을 받쳤고, 반대로 엔화가 너무 비싸지려 하면 엔화를 풀고 달러를 사들였다. 그래서 각국은 이 일에 쓸 달러를 넉넉히 쌓아 두어야 했다. 비율을 도저히 지킬 수 없을 만큼 사정이 바뀌면 국제통화기금(國際通貨基金 · International Monetary Fund, IMF)과 협의해 비율 자체를 고쳤다. 무역 결제의 기준이 달러로 모이면서 IMF 같은 협력 장치가 함께 섰다. 미국의 대외 지급이 늘고 금과의 교환을 유지하기 어려워지면서, 1970년대 초 고정 환율은 흔들렸다. 그 뒤 주요국 통화는 변동 환율 쪽으로 옮겨 갔다.",
