    "en": "stablecoin",
    "track": "crypto",
    "one": "담보를 잡거나 공급을 조절하는 방식에 따라 나뉘며, 기준이 되는 화폐 값에 붙어 있게 설계한 가상자산이다.",
    "body": "암호자산(暗號資産 · crypto-asset) 시장에서 거래 대기 자금이나 송금에 쓰려는 사람들이 보유한다. 법정화폐(法定貨幣 · legal tender)를 담보로 맡기는 형, 다른 암호자산을 담보로 잡는 형, 알고리즘으로 공급을 늘리고 줄이는 형이 있다. 담보형은 맡긴 자산이 약속과 같은 규모와 질이어야 값이 기준에 붙는다. 알고리즘형은 공급 조절이 설계대로 작동해야 같은 역할을 한다. 담보가 비거나 조절 규칙이 무너지면 기준 값 아래로 밀린다. 은행 예금이 아니고, 예금자 보호를 받는 돈도 아니다. 발행하는 것은 중앙은행이 아니라 민간 회사이다. 대표적인 달러 스테이블코인도 미국 연방준비제도가 아니라 민간 기업이 찍어 내고, 그 회사가 맡아 둔 달러 예금과 국채가 값을 받친다. 그래서 중앙은행이 직접 발행하고 책임지는 중앙은행 디지털화폐(CBDC)와는 다르다. 발행 회사가 중앙은행 노릇을 하는 것은 아니다. 금리를 정하거나 경기를 보며 돈의 양을 조절하지 않고, 하는 일은 하나이다. 1코인을 가져오면 언제든 1달러를 돌려주겠다는 약속(상환)을 지키는 것이다. 그러려면 발행한 코인만큼의 돈을 쥐고 있어야 하므로, 규제는 대개 받은 돈을 남에게 빌려주지 말고 현금과 짧은 국채처럼 바로 바꿀 수 있는 자산으로만 1대1로 들고 있게 한다. 예금의 일부만 남기고 나머지를 대출하는 은행보다 더 엄격한 셈이다. 그 돈이 정말 있는지에 대한 의심이 번지면 사람들이 한꺼번에 돌려받으려 몰려, 은행의 예금 인출 사태와 비슷한 일이 생길 수 있다. 중앙은행의 통제 아래 있지 않은 대신, 나라마다 금융 감독 당국이 발행 회사에 담보를 얼마나, 어떤 자산으로 쥐어야 하는지를 정하는 규제를 만들고 있다. 유럽연합과 미국은 2024~2025년에 관련 법을 시행하거나 만들었고, 우리나라는 원화 스테이블코인을 허용할지와 누가 발행할지를 논의하는 중이다. 2022년에는 알고리즘으로 값을 맞추던 한 스테이블코인이 하루 이틀 사이 기준 값에서 크게 떨어지며 무너진 일이 있었다.",
