    "body": "은행연합회가 8개 은행의 수신 자료를 모아 공시하고, 변동금리 주택담보대출을 다루는 은행과 그 대출을 가진 가계가 본다. 코픽스는 무엇을 넣어 평균하느냐에 따라 세 가지가 있다. 자금의 종류가 세 가지라는 뜻은 아니다. 은행이 수신으로 구한 돈은 정기예금, 정기적금, 양도성예금증서(CD), 환매조건부채권(RP), 은행채 같은 여러 상품이고, 세 코픽스는 이 돈을 두 가지 물음에 따라 다르게 골라 평균한 값이다. 하나는 언제 받은 돈을 넣느냐(이번 달에 새로 받은 것만인가, 지금 남아 있는 것 전부인가)이고, 다른 하나는 어디까지 넣느냐(이자가 붙는 상품만인가, 보통예금 같은 결제성 예금까지인가)이다. 신규취급액 기준은 그 달에 새로 받은 예금 등만 넣는다. 잔액 기준은 그 달 말에 은행에 남아 있는 예금 등(수신 잔액)을 모두 넣는다. 신잔액 기준(新殘額 基準)은 2019년 6월에 새로 만든 기준이라 \"새 잔액 기준\"이라는 뜻의 이름이 붙었고, 잔액 기준에 보통예금처럼 언제든 찾을 수 있어 이자가 거의 없는 결제성 예금까지 더 넣는다. 결제성 예금의 중심은 요구불예금(要求拂預金 · demand deposit)이다. 맡긴 사람이 요구(要求)하면 언제든 내준다(拂)는 뜻으로, 보통예금과 당좌예금이 여기에 든다. 이름은 저축성예금이지만 언제든 넣고 뺄 수 있는 수시입출식 저축성예금(기업자유예금, 시장금리부 수시입출식 예금 MMDA 등)도 결제에 쓰이므로 함께 넣는다. 둘 다 언제든 찾을 수 있는데 수시입출식 저축성예금의 이자가 더 높은 까닭은 둘이다. 하나는 쓰임이 다르다는 것이다. 요구불예금은 월급이 들어오고 카드값과 공과금이 빠져나가는 결제용 통장이어서, 예금자는 이자보다 편리함을 보고 두며 잘 옮기지 않는다. 수시입출식 저축성예금은 수표 발행이나 일부 자동이체가 안 되거나, 잔액이 일정 금액 넘을 때만 높은 금리를 주는 식으로 결제 기능을 줄이고 그 대신 이자를 준다. 다른 하나는 은행이 그 돈을 붙잡으려면 이자를 줘야 한다는 것이다. 이 돈은 이자를 보고 들어온 돈이라 다른 곳이 더 주면 하루 만에 옮겨 간다. 그래서 은행은 증권사의 CMA나 MMF 같은 상품과 견줄 만한 금리를 준다. 이른바 파킹통장도 이런 경쟁 속에 인터넷은행과 저축은행이 손님을 끌려고 내놓은 상품이 많고, 높은 금리를 일정 금액까지만 주는 경우가 많다. 법으로 나눈 이름보다 그 통장으로 무엇을 할 수 있고 금리가 어떤 조건에 붙는지가 실제 차이를 만든다. 그래서 경제적으로는 둘을 사실상 같은 돈으로 본다. 한국은행도 바로 결제에 쓸 수 있는 돈을 세는 협의통화(M1)에 현금, 요구불예금, 수시입출식 저축성예금을 함께 넣고, 신잔액 기준 코픽스도 둘을 함께 넣는다. 이름이 나뉘어 남은 데에는 역사가 있다. 예전에는 정부가 예금 금리의 상한을 정했고 요구불예금 금리는 2004년에야 자유화되었다. 그 전에 은행들이 언제든 찾을 수 있으면서 이자를 더 주는 상품을 내놓으려면, 금리 규제가 먼저 풀린 저축성예금의 이름을 빌려야 했다. 1997년에 나온 MMDA가 그런 예이다. 은행의 보통예금 금리는 대개 연 0.1% 안팎이고, 기업이 수표와 어음 결제에 쓰는 당좌예금은 이자가 없다. 은행이 이런 예금에 이자를 거의 주지 않아도 되는 것은 예금자가 이자보다 언제든 찾고 보낼 수 있는 편리함을 보고 맡기기 때문이다. 다만 언제든 찾을 수 있으면서 연 2% 안팎을 주는 이른바 파킹통장처럼, 금리가 높은 수시입출식 상품도 있다. 예를 들어 한 은행에 예전에 연 4%로 받은 정기예금 300조 원이 남아 있고, 이번 달에 연 3%로 정기예금 20조 원을 새로 받았으며, 이자가 연 0.1%인 보통예금이 100조 원 있다고 하자. 신규취급액 기준은 이번 달 것만 보니 3.00%, 잔액 기준은 정기예금 320조 원을 평균해 (300 × 4% + 20 × 3%) ÷ 320 ≈ 3.94%, 신잔액 기준은 보통예금 100조 원까지 넣어 ≈ 3.02%가 된다. 시장 금리가 내리면 새로 받는 예금의 금리는 바로 내려가지만, 예전에 받은 정기예금은 만기까지 옛 금리를 그대로 주므로, 신규취급액 기준은 빨리 움직이고 잔액 기준은 천천히 따라간다. 신잔액 기준은 금리가 낮은 결제성 예금이 섞여 수준이 가장 낮고, 그 예금 금리는 시장 금리가 바뀌어도 거의 그대로라 움직임도 가장 완만하다. 단기 지표는 만기가 짧은 조달 비용에 초점을 맞춘다. 이런 대출은 고른 지표에 가산금리를 더해 금리를 정하므로, 지표가 오르면 이자 부담이 커지고 내리면 작아진다. 정책금리 그 자체는 아니라서 수신 경쟁에 따라 정책금리와 다른 폭으로 움직인다.",
