    "body": "지급여력비율은 손실을 흡수할 가용자본(可用資本 · available capital)을, 위험이 요구하는 자본(요구자본 要求資本 · required capital)으로 나눈 값이다. K-ICS비율은 그 나눗셈을 한국 보험자본기준인 K-ICS로 잰 비율로, 자산과 부채를 시가에 가깝게 보고 위험 종류별로 요구자본을 쌓는다. 금리 변동이 보험 부채 가치에 빨리 반영되므로, 자산과 부채의 만기가 어긋나면 비율이 민감하게 움직인다. 비율이 낮아지면 완충이 얇아져 자본 확충이나 위험자산 축소 압력이 생기고, 높아지면 버퍼는 두꺼워진다. 숫자가 높다고 보험금이 늘 차질 없다는 뜻은 아니고, 어떤 기준으로 재었는지를 같이 봐야 한다.",
