    "one": "여신은 금융회사가 돈을 빌려주는 것, 수신은 금융회사가 돈을 맡아 두는 것을 가리키는 말이다.",
    "body": "한국은행만 쓰는 말이 아니라 은행과 저축은행, 카드회사 같은 금융회사, 감독당국, 금융 기사에서 두루 쓰는 업계의 말이다. 은행 안에서는 여신심사, 여신 담당, 수신 상품처럼 부서와 업무 이름에 쓰이고, 은행 공시와 기사에서는 여신 잔액, 수신 금리처럼 쓴다. 다만 고객을 대하는 창구와 앱에서는 대개 대출과 예금이라는 쉬운 말을 쓴다. 그래서 수신 자료, 수신 금리라고 하면 예금 쪽 정보로 읽으면 된다. 다만 한국은행 통계의 수신에는 보통 예금과 적금 말고도 양도성예금증서(CD)나 고객에게 판 RP처럼 은행이 고객 돈을 짧게 받아 두는 상품이 함께 들어간다. 예대금리차 카드의 지금 숫자에 나오는 \"예금은행 수신금리\"도 이렇게 넓게 센 숫자이다. 여신(與信)은 \"믿음을 준다\"는 뜻으로, 상대가 갚으리라 믿고 돈을 내주는 대출, 지급보증, 카드 결제 한도 같은 것을 아우른다. 수신(受信)은 \"믿음을 받는다\"는 뜻으로, 고객이 금융회사를 믿고 맡긴 예금과 적금 같은 것이다. 은행은 수신으로 모은 돈을 여신으로 내주고, 여신에서 받는 이자와 수신에 주는 이자의 차이(예대금리차)로 돈을 번다. 같은 거래도 보는 쪽에 따라 이름이 바뀐다. 고객이 은행에 1억 원을 맡기면 은행에게는 수신 1억 원이고, 은행이 기업에 5억 원을 빌려주면 은행에게는 여신 5억 원이다. 한국은행이 은행과 하는 자금조정대출과 자금조정예금도 한국은행 쪽에서 보아 여신과 수신이라 부르며, 둘을 묶은 이름이 대기성 여수신제도이다. 여신 잔액, 수신 잔액의 잔액(殘額 · outstanding balance)은 어느 날 기준으로 아직 남아 있는 금액이다. 여신 잔액은 은행이 빌려주고 아직 돌려받지 못한 대출의 합계이고, 수신 잔액은 고객이 맡기고 아직 찾아가지 않은 예금의 합계이다. 한 달 동안 새로 나간 대출만 센 신규 취급액과는 다르다.",
    "watch": "여신전문금융회사의 여신은 예금을 받지 않고 대출과 카드, 할부, 리스만 하는 회사라는 뜻이다. 수신 없이 여신만 한다는 말이다.",
